<?php
declare(strict_types=1);
use App\Service\{BillingService,BillingSchema,BookingPolicy,BookingClock,StaffReservationService,StaffAuthService,OrderService};
use App\Core\StaffAccess;
$t=new BookingHarness();
if(!(new BookingPolicy($t->pdo))->bellaVista())throw new RuntimeException('Billing tests need the isolated target catalog.');
if(!defined('BILLING_FIXTURE_ONLY'))BillingSchema::prepare($t->pdo);
// Take the fixture snapshot after activation so reset preserves the explicit billing flag.
$t=new BookingHarness();
function billingActor(BookingHarness $t,string $role='admin'):array{
 $q=$t->pdo->prepare('SELECT id FROM roles WHERE code=?');$q->execute([$role]);$id=$q->fetchColumn();
 $t->pdo->prepare("INSERT INTO users(role_id,email,full_name,is_active,password_hash) VALUES (?,?,?,1,?) ON DUPLICATE KEY UPDATE role_id=VALUES(role_id),is_active=1,password_hash=VALUES(password_hash)")->execute([$id,'b3-'.$role.'@lumina.test','B3 '.$role,StaffAuthService::password('Isolated billing passphrase 2026!')]);
 $q=$t->pdo->prepare('SELECT * FROM users WHERE email=?');$q->execute(['b3-'.$role.'@lumina.test']);$u=$q->fetch();return ['id'=>(int)$u['id'],'stamp'=>StaffAccess::stamp($u)];
}
function billingKey():string{$h=bin2hex(random_bytes(16));return substr($h,0,8).'-'.substr($h,8,4).'-'.substr($h,12,4).'-'.substr($h,16,4).'-'.substr($h,20);}
function billingBooking(BookingHarness $t,string $category='bv_family',int $party=5,int $food=200000):array{
 $h=$t->service->hold($t->date,'10:00',$party,$category,$t->owner);$r=$t->service->confirm($h['hold_token'],$t->guest,$t->owner);
 $q=$t->pdo->prepare('SELECT id FROM reservations WHERE code=?');$q->execute([$r['code']]);$id=(int)$q->fetchColumn();$q=$t->pdo->prepare('SELECT table_id FROM reservation_tables WHERE reservation_id=?');$q->execute([$id]);$tid=(int)$q->fetchColumn();
 $t->pdo->prepare("UPDATE reservations SET status='seated' WHERE id=?")->execute([$id]);
 if($food>0){$t->pdo->prepare("INSERT INTO orders(reservation_id,table_id,status,total_cents,subtotal_cents) VALUES (?,?,'closed',?,?)")->execute([$id,$tid,$food,$food]);$oid=(int)$t->pdo->lastInsertId();$item=(int)$t->pdo->query('SELECT id FROM menu_items LIMIT 1')->fetchColumn();$t->pdo->prepare("INSERT INTO order_items(order_id,menu_item_id,qty,unit_price_cents,status,item_name,station_snapshot) VALUES (?,?,1,?,'served','Billing food','hot')")->execute([$oid,$item,$food]);}
 return $r+['id'=>$id,'table_id'=>$tid];
}
function billing(BookingHarness $t):BillingService{return new BillingService($t->pdo,new BookingClock($t->pdo));}
function receipt(BookingHarness $t,array $a,int $id,string $kind,int $cents,?string $key=null):array{$s=billing($t);$q=$s->quote($a,$id);return $s->mutate($a,$id,$kind,$q['revision'],$key??billingKey(),['amount_cents'=>$cents,'method'=>'cash','reason'=>'Isolated receipt']);}
if(defined('BILLING_FIXTURE_ONLY'))return;
$t->test('B3 explicit billing service exists',fn($t)=>$t->assert(class_exists(BillingService::class),'Missing transaction-safe billing service'));
$t->test('B3 assessed fee is not paid and food subtotal is server-owned',function($t){$r=billingBooking($t);$a=billingActor($t);$q=billing($t)->quote($a,$r['id']);$t->assert($q['base_fee_cents']===50000&&$q['received_cents']===0&&$q['due_cents']===200000);$t->assert($t->count('billing_accounts')===0,'Read-only quote must not create history');});
$t->test('B3 paid base credit applies once across multiple food rounds',function($t){$r=billingBooking($t);$a=billingActor($t);$q=receipt($t,$a,$r['id'],'advance',50000)['bill'];$t->assert($q['due_cents']===150000&&$q['credit_applied_cents']===50000);$t->pdo->prepare("INSERT INTO orders(reservation_id,table_id,status) VALUES (?,?,'closed')")->execute([$r['id'],$r['table_id']]);$oid=(int)$t->pdo->lastInsertId();$mid=(int)$t->pdo->query('SELECT menu_item_id FROM order_items LIMIT 1')->fetchColumn();$t->pdo->prepare("INSERT INTO order_items(order_id,menu_item_id,qty,unit_price_cents,status) VALUES (?,?,1,100000,'served')")->execute([$oid,$mid]);$q=billing($t)->quote($a,$r['id']);$t->assert($q['due_cents']===250000&&$q['credit_applied_cents']===50000);});
$t->test('B3 VIP extra cannot consume unused base food credit',function($t){$r=billingBooking($t,'bv_vip',16,200000);$a=billingActor($t);$q=receipt($t,$a,$r['id'],'advance',250000)['bill'];$t->assert($q['due_cents']===30000&&$q['unused_credit_cents']===50000);});
$t->test('B3 direct onsite payment does not add base fee again',function($t){$r=billingBooking($t);$a=billingActor($t);$q=receipt($t,$a,$r['id'],'payment',200000)['bill'];$t->assert($q['due_cents']===0&&$q['received_cents']===200000);$q=billing($t)->mutate($a,$r['id'],'finalize',$q['revision'],billingKey(),[])['bill'];$t->assert($q['status']==='finalized');});
$t->test('B3 partial receipts, exact replay and changed-payload rejection',function($t){$r=billingBooking($t);$a=billingActor($t);$s=billing($t);$q=$s->quote($a,$r['id']);$key=billingKey();$data=['amount_cents'=>70000,'method'=>'external_card','reason'=>'External card completed'];$one=$s->mutate($a,$r['id'],'payment',$q['revision'],$key,$data);$two=$s->mutate($a,$r['id'],'payment',$q['revision'],$key,$data);$t->assert($two['replayed']&&$one['bill']['due_cents']===130000&&$t->count('billing_events')===1);$data['amount_cents']=80000;$t->expectError('request_changed',fn()=>$s->mutate($a,$r['id'],'payment',$q['revision'],$key,$data));});
$t->test('B3 stale quote and tampered or overpaid amounts are rejected',function($t){$r=billingBooking($t);$a=billingActor($t);$s=billing($t);$q=$s->quote($a,$r['id']);$t->pdo->exec('UPDATE order_items SET unit_price_cents=210000');$t->expectError('bill_changed',fn()=>$s->mutate($a,$r['id'],'payment',$q['revision'],billingKey(),['amount_cents'=>200000,'method'=>'cash','reason'=>'Old quote']));$t->expectError('invalid_amount',fn()=>receipt($t,$a,$r['id'],'payment',210001));$t->expectError('invalid_amount',fn()=>receipt($t,$a,$r['id'],'advance',50001));$t->assert($t->count('billing_accounts')===0);});
$t->test('B3 kitchen/server/host cannot record or view cashier money',function($t){$r=billingBooking($t);foreach(['host','server','kitchen'] as $role){$a=billingActor($t,$role);$t->expectError('staff_forbidden',fn()=>billing($t)->quote($a,$r['id']));}});
$t->test('B3 unused actual credit requires reviewed recorded refund before closure',function($t){$r=billingBooking($t,'bv_family',5,40000);$a=billingActor($t);$s=billing($t);$q=receipt($t,$a,$r['id'],'advance',50000)['bill'];$t->expectError('unused_credit',fn()=>$s->mutate($a,$r['id'],'finalize',$q['revision'],billingKey(),[]));$q=receipt($t,$a,$r['id'],'refund_credit',10000)['bill'];$t->assert($q['unused_credit_cents']===0&&$q['received_cents']===40000);});
$t->test('B3 financial history blocks permanent deletion and incompatible changes',function($t){$r=billingBooking($t);$a=billingActor($t);receipt($t,$a,$r['id'],'advance',50000);$t->pdo->exec("UPDATE reservations SET status='cancelled'");$t->expectError('booking_has_billing',fn()=>(new StaffReservationService($t->pdo,new BookingClock($t->pdo)))->delete($a,$r['code'],1));});
$t->test('B3 Standard seating below minimum rolls back its provisional order',function($t){$r=billingBooking($t,'bv_standard',2,0);$a=billingActor($t);$t->pdo->exec("UPDATE reservations SET status='confirmed'");$clock=new BookingClock($t->pdo,fn()=>new DateTimeImmutable($t->date.' 09:45:00',new DateTimeZone('Asia/Manila')));$s=new StaffReservationService($t->pdo,$clock);$item=$t->pdo->query('SELECT id,price_cents FROM menu_items WHERE is_available=1 AND price_cents<100000 ORDER BY price_cents LIMIT 1')->fetch();$t->expectError('minimum_not_met',fn()=>$s->transition($a,$r['code'],1,'seat','Minimum boundary test',[['id'=>(int)$item['id'],'qty'=>1]]));$t->assert($t->count('orders')===0);$qty=(int)ceil(100000/(int)$item['price_cents']);$s->transition($a,$r['code'],1,'seat','Minimum satisfied',[['id'=>(int)$item['id'],'qty'=>$qty]]);$t->assert($t->count('orders')===1&&$t->pdo->query('SELECT status FROM reservations')->fetchColumn()==='seated');});
$t->test('B3 simultaneous bill payments produce one receipt and one stale-quote refusal',function($t){$r=billingBooking($t);$a=billingActor($t);$q=billing($t)->quote($a,$r['id']);$jobs=[];foreach([1,2] as $i)$jobs[]=['op'=>'billing','actor'=>$a,'id'=>$r['id'],'action'=>'payment','revision'=>$q['revision'],'key'=>billingKey(),'data'=>['amount_cents'=>150000,'method'=>'cash','reason'=>'Simultaneous receipt']];$results=$t->finishWorkers($t->startWorkers($jobs));$t->assert(count(array_filter($results,fn($r)=>$r['ok']))===1&&$t->count('billing_events')===1);$t->assert(billing($t)->quote($a,$r['id'])['due_cents']===50000);});
$t->test('B3 concurrent exact receipt retry creates one event',function($t){$r=billingBooking($t);$a=billingActor($t);$q=billing($t)->quote($a,$r['id']);$job=['op'=>'billing','actor'=>$a,'id'=>$r['id'],'action'=>'payment','revision'=>$q['revision'],'key'=>billingKey(),'data'=>['amount_cents'=>200000,'method'=>'cash','reason'=>'Same receipt retry']];$results=$t->finishWorkers($t->startWorkers([$job,$job]));$t->assert(count(array_filter($results,fn($r)=>$r['ok']))===2&&$t->count('billing_events')===1);});
$t->test('B3 finalized bill prevents edits through the existing order API',function($t){$r=billingBooking($t);$a=billingActor($t);$q=receipt($t,$a,$r['id'],'payment',200000)['bill'];billing($t)->mutate($a,$r['id'],'finalize',$q['revision'],billingKey(),[]);$id=(int)$t->pdo->query('SELECT id FROM orders')->fetchColumn();$t->expectError('bill_finalized',fn()=>(new OrderService($t->pdo,new BookingClock($t->pdo)))->mutate($a,$id,1,'void',billingKey(),['reason'=>'Trying old route']));});
$t->test('B3 Standard void below minimum rolls back item and order changes',function($t){$r=billingBooking($t,'bv_standard',2,100000);$a=billingActor($t);$t->pdo->exec("UPDATE orders SET status='open'");$id=(int)$t->pdo->query('SELECT id FROM orders')->fetchColumn();$t->expectError('minimum_not_met',fn()=>(new OrderService($t->pdo,new BookingClock($t->pdo)))->mutate($a,$id,1,'void',billingKey(),['reason'=>'Minimum rollback']));$t->assert($t->pdo->query('SELECT status FROM order_items')->fetchColumn()==='served');});
$t->test('B3 partial served meal cannot settle or finalize early',function($t){$r=billingBooking($t);$a=billingActor($t);$t->pdo->exec("UPDATE order_items SET status='preparing'");$t->expectError('food_not_served',fn()=>receipt($t,$a,$r['id'],'payment',200000));$t->assert($t->count('billing_events')===0);});
$t->test('B3 cancellation refunds cannot bypass same-day policy through unused-credit action',function($t){$r=billingBooking($t,'bv_family',5,0);$a=billingActor($t);receipt($t,$a,$r['id'],'advance',50000);$t->pdo->exec("UPDATE reservations SET status='cancelled'");$t->expectError('billing_stage',fn()=>receipt($t,$a,$r['id'],'refund_credit',50000));});
$t->test('B3 existing order API cannot create an unbillable money overflow',function($t){$r=billingBooking($t);$a=billingActor($t);$t->pdo->exec("UPDATE orders SET status='open'");$id=(int)$t->pdo->query('SELECT id FROM orders')->fetchColumn();$mid=(int)$t->pdo->query('SELECT id FROM menu_items WHERE is_available=1 LIMIT 1')->fetchColumn();$t->pdo->prepare('UPDATE menu_items SET price_cents=10000000 WHERE id=?')->execute([$mid]);$t->expectError('invalid_amount',fn()=>(new OrderService($t->pdo,new BookingClock($t->pdo)))->mutate($a,$id,1,'add',billingKey(),['menu_item_id'=>$mid,'qty'=>11,'course_no'=>1,'notes'=>'']));});
$t->test('B3 below-base direct onsite and partial-advance bills can close after explicit manager review',function($t){
 $r=billingBooking($t,'bv_family',5,40000);$a=billingActor($t);$s=billing($t);$q=receipt($t,$a,$r['id'],'payment',40000)['bill'];
 $t->expectError('fee_review_required',fn()=>$s->mutate($a,$r['id'],'finalize',$q['revision'],billingKey(),[]));
 $q=$s->mutate($a,$r['id'],'finalize',$q['revision'],billingKey(),['review_reason'=>'Reviewed unused unpaid allowance; no additional food minimum'])['bill'];
 $t->assert($q['status']==='finalized'&&$q['received_cents']===40000&&$q['base_fee_cents']===50000);
});
$t->test('B3 below-base partial advance does not create an extra food minimum',function($t){$r=billingBooking($t,'bv_family',5,40000);$a=billingActor($t);$s=billing($t);receipt($t,$a,$r['id'],'advance',20000);$q=receipt($t,$a,$r['id'],'payment',20000)['bill'];$q=$s->mutate($a,$r['id'],'finalize',$q['revision'],billingKey(),['review_reason'=>'Manager reviewed residual unreceived consumable allowance'])['bill'];$t->assert($q['status']==='finalized'&&$q['received_cents']===40000);});
$t->finish();
